Original comment:

One workaround I am currently using is following:

opencode.json
``` opencode.json
{
  "$schema": "https://opencode.ai/config.json",

  "lsp": {
    "typescript": {
      "command": ["node", "scripts/opencode-tsgo-lsp-proxy.cjs"],
      "extensions": [".cjs", ".mjs", ".js", ".jsx", ".ts", ".tsx", ".mts", ".cts"]
    }
  }
}
```

scripts/opencode-tsgo-lsp-proxy.cjs
``` scripts/opencode-tsgo-lsp-proxy.cjs
#!/usr/bin/env node

const { spawn } = require("child_process")
const fs = require("fs")
const path = require("path")

const tsgoBin = path.resolve(process.cwd(), "node_modules/.bin/tsgo")
const tsgoCommand = fs.existsSync(tsgoBin) ? tsgoBin : "tsgo"

const server = spawn(tsgoCommand, ["--lsp", "--stdio"], {
  stdio: ["pipe", "pipe", "pipe"],
  env: process.env,
})

let nextRequestId = 900000000
const proxyDiagnosticRequestById = new Map()
const latestResultIdByUri = new Map()
const inFlightByUri = new Map()
const rerunByUri = new Set()
const debounceTimerByUri = new Map()
let supportsTextDocumentDiagnostic = true

const writeFrame = (stream, message) => {
  const body = JSON.stringify(message)
  stream.write(`Content-Length: ${Buffer.byteLength(body, "utf8")}\r\n\r\n${body}`)
}

const forwardToClient = (message) => writeFrame(process.stdout, message)
const forwardToServer = (message) => writeFrame(server.stdin, message)

const scheduleDiagnostic = (uri) => {
  if (!uri || !supportsTextDocumentDiagnostic) return
  const existingTimer = debounceTimerByUri.get(uri)
  if (existingTimer) clearTimeout(existingTimer)
  const timer = setTimeout(() => {
    debounceTimerByUri.delete(uri)
    requestDiagnostic(uri)
  }, 120)
  debounceTimerByUri.set(uri, timer)
}

const requestDiagnostic = (uri) => {
  if (!supportsTextDocumentDiagnostic) return
  if (inFlightByUri.has(uri)) {
    rerunByUri.add(uri)
    return
  }

  const id = nextRequestId++
  inFlightByUri.set(uri, id)
  proxyDiagnosticRequestById.set(id, uri)

  const previousResultId = latestResultIdByUri.get(uri)
  const params = {
    textDocument: { uri },
  }

  if (typeof previousResultId === "string" && previousResultId.length > 0) {
    params.previousResultId = previousResultId
  }

  forwardToServer({
    jsonrpc: "2.0",
    id,
    method: "textDocument/diagnostic",
    params,
  })
}

const handleProxyDiagnosticResponse = (responseId, result, error) => {
  const uri = proxyDiagnosticRequestById.get(responseId)
  if (!uri) return false

  proxyDiagnosticRequestById.delete(responseId)
  inFlightByUri.delete(uri)

  if (error) {
    supportsTextDocumentDiagnostic = false
  } else if (result && typeof result === "object") {
    if (typeof result.resultId === "string") {
      latestResultIdByUri.set(uri, result.resultId)
    }
    if (result.kind === "full" && Array.isArray(result.items)) {
      forwardToClient({
        jsonrpc: "2.0",
        method: "textDocument/publishDiagnostics",
        params: {
          uri,
          diagnostics: result.items,
        },
      })
    }
  }

  if (rerunByUri.has(uri)) {
    rerunByUri.delete(uri)
    requestDiagnostic(uri)
  }

  return true
}

const onClientMessage = (message) => {
  forwardToServer(message)

  if (!message || typeof message !== "object" || typeof message.method !== "string") return

